css:
.loader { position: relative; display: inline-flex; align-items: center; width: var(--loader-size); padding: calc(var(--loader-size) * .09) calc(var(--loader-size) * .14); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 15%, transparent); box-sizing: border-box; }
.loader .bar { flex: 1; height: calc(var(--loader-size) * .07); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 55%, transparent); }
.loader .dot { position: absolute; top: calc(var(--loader-size) * -.04); right: calc(var(--loader-size) * -.04); width: calc(var(--loader-size) * .16); height: calc(var(--loader-size) * .16); border-radius: 9999px; background: var(--loader-secondary-color); animation: twPingDot calc(var(--loader-speed) * 1.4) cubic-bezier(0, 0, .2, 1) infinite; }
@keyframes twPingDot { 0% { box-shadow: 0 0 0 0 var(--loader-secondary-color); } 70%, 100% { box-shadow: 0 0 0 calc(var(--loader-size) * .14) transparent; } }
